WITH rc AS (
  SELECT uuid, COUNT(*) AS n FROM rulings GROUP BY uuid
), mx AS (
  SELECT MAX(n) AS m FROM rc
)
SELECT DISTINCT c.name, c.artist, c.ispromo
FROM rc
JOIN mx ON rc.n = mx.m
JOIN cards c ON c.uuid = rc.uuid
ORDER BY 1,2,3;

